toolArgs.file_text:
@* Search bar for filtering tasks by title *@

<div class="search-bar">
    <input type="text" placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter]
    public string SearchText { get; set; } = "";

    [Parameter]
    public EventCallback<string> SearchTextChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? "";
        await SearchTextChanged.InvokeAsync(value);
    }
}

@* A single Kanban column with header, task cards, and add-task form *@

<div class="board-column">
    <div class="column-header">
        <h3>@ColumnName</h3>
        <span class="column-count">@Tasks.Count</span>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      OnMoveLeft="HandleMoveLeft"
                      OnMoveRight="HandleMoveRight" />
        }
    </div>
    <div class="column-footer">
        <AddTaskForm OnSave="HandleAddTask" />
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public string ColumnName { get; set; } = "";

    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public bool ShowMoveLeft { get; set; }

    [Parameter]
    public bool ShowMoveRight { get; set; }

    [Parameter]
    public string? MoveLeftStatus { get; set; }

    [Parameter]
    public string? MoveRightStatus { get; set; }

    [Parameter]
    public EventCallback<(int TaskId, string NewStatus)> OnTaskMoved { get; set; }

    [Parameter]
    public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnTaskCreated { get; set; }

    private async Task HandleMoveLeft(int taskId)
    {
        if (MoveLeftStatus is not null)
            await OnTaskMoved.InvokeAsync((taskId, MoveLeftStatus));
    }

    private async Task HandleMoveRight(int taskId)
    {
        if (MoveRightStatus is not null)
            await OnTaskMoved.InvokeAsync((taskId, MoveRightStatus));
    }

    private async Task HandleAddTask((string Title, string Assignee, string Priority, DateTime DueDate) formData)
    {
        await OnTaskCreated.InvokeAsync(formData);
    }
}

arguments.file_text:
@page "/board"
@rendermode InteractiveServer
@using sv_df7227fb0b2c47099ed90bde76b0d8f2.Components.Board
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2>Kanban Board</h2>

@if (isLoading)
{
    <p class="board-loading">Loading tasks…</p>
}
else if (errorMessage is not null)
{
    <div class="board-error">
        <p>@errorMessage</p>
        <button @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardSummaryBar TotalCount="allTasks.Count"
                     TodoCount="GetColumnTasks("To Do", allTasks).Count"
                     InProgressCount="GetColumnTasks("In Progress", allTasks).Count"
                     DoneCount="GetColumnTasks("Done", allTasks).Count"
                     OverdueCount="allTasks.Count(t => t.DueDate < DateTime.Today)" />

    <BoardSearchBar @bind-SearchText="searchText" />

    <div class="board-columns">
        <BoardColumn ColumnName="To Do"
                     Tasks="GetColumnTasks("To Do", filteredTasks)"
                     ShowMoveLeft="false"
                     ShowMoveRight="true"
                     MoveRightStatus="In Progress"
                     OnTaskMoved="HandleTaskMoved"
                     OnTaskCreated="args => HandleTaskCreated(args, "To Do")" />

        <BoardColumn ColumnName="In Progress"
                     Tasks="GetColumnTasks("In Progress", filteredTasks)"
                     ShowMoveLeft="true"
                     ShowMoveRight="true"
                     MoveLeftStatus="To Do"
                     MoveRightStatus="Done"
                     OnTaskMoved="HandleTaskMoved"
                     OnTaskCreated="args => HandleTaskCreated(args, "In Progress")" />

        <BoardColumn ColumnName="Done"
                     Tasks="GetColumnTasks("Done", filteredTasks)"
                     ShowMoveLeft="true"
                     ShowMoveRight="false"
                     MoveLeftStatus="In Progress"
                     OnTaskMoved="HandleTaskMoved"
                     OnTaskCreated="args => HandleTaskCreated(args, "Done")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = "";
    private bool isLoading = true;
    private string? errorMessage;

    private List<TaskItem> filteredTasks =>
        string.IsNullOrWhiteSpace(searchText)
            ? allTasks
            : allTasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private static List<TaskItem> GetColumnTasks(string status, List<TaskItem> tasks) =>
        tasks.Where(t => t.Status == status).ToList();

    private async Task HandleTaskMoved((int TaskId, string NewStatus) args)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(args.TaskId, args.NewStatus);
            var task = allTasks.First(t => t.Id == args.TaskId);
            var index = allTasks.IndexOf(task);
            allTasks[index] = task with { Status = args.NewStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task HandleTaskCreated(
        (string Title, string Assignee, string Priority, DateTime DueDate) args,
        string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(args.Title, args.Assignee, args.Priority, args.DueDate);
            allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

h2 {
    margin-bottom: 1rem;
}

/* Summary Bar */
.summary-bar {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 1rem;
}

.summary-stat {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.stat-label {
    font-size: 0.8rem;
    color: #6c757d;
    text-transform: uppercase;
}

.stat-value {
    font-size: 1.4rem;
    font-weight: 700;
}

.summary-overdue .stat-value {
    color: #dc3545;
}

/* Search Bar */
.search-bar {
    margin-bottom: 1rem;
}

.search-bar input {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 6px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

/* Board Columns */
.board-columns {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
}

.board-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 8px;
    padding: 0.75rem;
    min-height: 200px;
    display: flex;
    flex-direction: column;
}

.column-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.column-header h3 {
    margin: 0;
    font-size: 1rem;
}

.column-count {
    background: #dee2e6;
    border-radius: 12px;
    padding: 0.1rem 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
}

.column-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.column-footer {
    margin-top: 0.75rem;
}

/* Task Card */
.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 0.65rem;
}

.task-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.35rem;
}

.task-title {
    font-weight: 600;
    font-size: 0.9rem;
}

.priority-badge {
    font-size: 0.7rem;
    padding: 0.15rem 0.45rem;
    border-radius: 4px;
    font-weight: 600;
    text-transform: uppercase;
}

.priority-high {
    background: #dc3545;
    color: #fff;
}

.priority-medium {
    background: #ffc107;
    color: #212529;
}

.priority-low {
    background: #28a745;
    color: #fff;
}

.task-details {
    display: flex;
    justify-content: space-between;
    font-size: 0.8rem;
    color: #6c757d;
    margin-bottom: 0.4rem;
}

.task-actions {
    display: flex;
    gap: 0.4rem;
}

.btn-move {
    flex: 1;
    padding: 0.25rem 0.4rem;
    font-size: 0.75rem;
    border: 1px solid #ced4da;
    background: #fff;
    border-radius: 4px;
    cursor: pointer;
}

.btn-move:hover {
    background: #e9ecef;
}

/* Add Task Form */
.btn-add-task {
    width: 100%;
    padding: 0.4rem;
    border: 1px dashed #adb5bd;
    background: transparent;
    border-radius: 6px;
    cursor: pointer;
    color: #6c757d;
    font-size: 0.85rem;
}

.btn-add-task:hover {
    background: #e9ecef;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.add-task-form input,
.add-task-form select {
    padding: 0.35rem 0.5rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 0.85rem;
}

.form-actions {
    display: flex;
    gap: 0.4rem;
}

.btn-save,
.btn-cancel {
    flex: 1;
    padding: 0.35rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-save {
    background: #0d6efd;
    color: #fff;
}

.btn-save:hover {
    background: #0b5ed7;
}

.btn-cancel {
    background: #6c757d;
    color: #fff;
}

.btn-cancel:hover {
    background: #5c636a;
}

/* Loading / Error */
.board-loading {
    text-align: center;
    color: #6c757d;
    padding: 2rem;
}

.board-error {
    text-align: center;
    color: #dc3545;
    padding: 2rem;
}

.board-error button {
    margin-top: 0.5rem;
    padding: 0.4rem 1rem;
    border: 1px solid #dc3545;
    background: #fff;
    color: #dc3545;
    border-radius: 4px;
    cursor: pointer;
}

